"""Materialize buffer assignments generated by model planners."""

from abc import ABC, abstractmethod
from collections import defaultdict
from dataclasses import replace
from typing import Any

from vllm.config import VllmConfig
from vllm.logger import logger
from vllm.v1.kv_cache_interface import KVCacheConfig, KVCacheSpec, KVCacheTensor

from vllm_ascend.utils import get_kv_cache_tensor_layers

from .layerwise_cache_layout import get_layerwise_kv_cache_specs
from .reuse_policy import LayerwiseReuseLayout, LayerwiseReusePlan, SpecReuseRules


class LayerwiseCachePlanner(ABC):
    @staticmethod
    def can_reuse_spec(spec: KVCacheSpec, rules: SpecReuseRules) -> bool:
        """Apply the nearest declared spec rule."""
        for spec_type in type(spec).__mro__:
            if spec_type not in rules:
                continue
            rule = rules[spec_type]
            result = rule(spec) if callable(rule) else rule
            if not isinstance(result, bool):
                raise TypeError("Spec reuse rules must return bool")
            return result
        raise ValueError(f"No reuse rule declared for cache spec {type(spec).__name__}")

    def __init__(
        self,
        config: KVCacheConfig,
        vllm_config: VllmConfig,
        extra_config: dict[str, Any],
        excluded_layer_names: set[str] | None = None,
    ) -> None:
        self.config = config
        self.vllm_config = vllm_config
        self.extra_config = extra_config
        self.specs = get_layerwise_kv_cache_specs(config)
        self.excluded_layer_names = frozenset(excluded_layer_names or ()) & self.specs.keys()

    @abstractmethod
    def build(self) -> LayerwiseReusePlan:
        """Generate model-valid buffer assignments honoring excluded_layer_names."""
        raise NotImplementedError

    @abstractmethod
    def validate(self, layout: LayerwiseReuseLayout) -> None:
        """Enforce the model's state and reuse constraints before publication."""
        raise NotImplementedError

    def apply(self) -> None:
        plan = self.build()
        layout = self.compile(self.config, plan)
        self.validate(layout)
        if layout.has_layer_reuse:
            if self.vllm_config.parallel_config.prefill_context_parallel_size > 1:
                raise NotImplementedError("Layerwise offload does not support prefill context parallelism.")
            logger.info(
                "Layerwise reuse maps %d descriptors onto %d physical slots; independent layers=%s.",
                len(self.config.kv_cache_tensors),
                len(layout.kv_cache_tensors),
                layout.independent_layers,
            )
            self.config.kv_cache_tensors = list(layout.kv_cache_tensors)
            self.config.layerwise_kv_cache_reuse = True
        self.config.layerwise_reuse_layout = layout
        if plan.draft_layer_names:
            self.config.layerwise_draft_layer_names = tuple(sorted(plan.draft_layer_names))

    @staticmethod
    def compile(config: KVCacheConfig, plan: LayerwiseReusePlan) -> LayerwiseReuseLayout:
        specs = get_layerwise_kv_cache_specs(config)
        eligible = {name for slot in plan.buffer_slots for name in slot}
        tensors = config.kv_cache_tensors
        new_tensors: list[KVCacheTensor] = []
        for tensor in tensors:
            original_names = get_kv_cache_tensor_layers(tensor)
            names = [name for name in original_names if name not in eligible]
            if tensor.layer_stride and len(names) != len(original_names):
                new_tensors.extend(
                    KVCacheTensor(
                        size=config.num_blocks * specs[name].page_size_bytes,
                        layers=[name],
                        layer_stride=0,
                        offset=0,
                        block_stride=specs[name].page_size_bytes,
                    )
                    for name in names
                )
            elif names:
                new_tensors.append(replace(tensor, layers=names))
        group_ids = {name: index for index, group in enumerate(config.kv_cache_groups) for name in group.layer_names}
        dependencies: dict[int, set[int]] = defaultdict(set)
        reused_names: set[str] = set()
        for names in plan.buffer_slots:
            if not names:
                raise ValueError("Reusable buffers cannot be empty")
            page_sizes = {specs[name].page_size_bytes for name in names}
            if len(page_sizes) != 1:
                raise ValueError("Reusable byte views must have aligned page sizes")
            previous: dict[int, str] = {}
            for name in sorted(names, key=plan.layer_indices.__getitem__):
                layer, group_id = plan.layer_indices[name], group_ids[name]
                if group_id in previous:
                    predecessor = plan.layer_indices[previous[group_id]]
                    if predecessor == layer:
                        raise ValueError("Simultaneous cache components cannot share a reuse slot")
                    dependencies[layer].add(predecessor)
                    reused_names.update((previous[group_id], name))
                previous[group_id] = name
            page_size = page_sizes.pop()
            new_tensors.append(
                KVCacheTensor(
                    size=config.num_blocks * page_size,
                    layers=list(names),
                    layer_stride=0,
                    offset=0,
                    block_stride=page_size,
                )
            )
        if sum(t.size for t in new_tensors) >= sum(t.size for t in tensors):
            dependencies.clear()
            reused_names.clear()
            new_tensors = list(tensors)
        return LayerwiseReuseLayout(
            layers=tuple(
                sorted({layer for name, layer in plan.layer_indices.items() if name not in plan.draft_layer_names})
            ),
            cache_layer_indices=dict(plan.layer_indices),
            kv_cache_tensors=tuple(new_tensors),
            prefetch_layer_map={layer: tuple(sorted(sources)) for layer, sources in dependencies.items()},
            independent_layers=plan.independent_layers,
            num_prefetch_layers=plan.num_prefetch_layers,
            reused_cache_names=frozenset(reused_names),
        )
